  'published', 10,
  '[{"id":"s_warm_welcome","scope":"lead","kind":"section","label":"Warm welcome","origin":"spine","locked":true},{"id":"s_open","scope":"lead","kind":"section","label":"Opening","origin":"spine","locked":true},{"id":"script_intro","scope":"lead","kind":"script","label":"Intro (read verbatim)","script":"Thank you. My name is ___. I''m calling from Turnbull, Moak, and Pendergrass, the law firm handling your claim. Before we begin, are you in a safe place to speak right now?","agentNote":"If NOT in a safe place: schedule a callback and stop here.","origin":"script","locked":true},{"id":"safe_to_speak","scope":"lead","kind":"gate","label":"Is the claimant in a safe place to speak?","gateType":"safety","agentNote":"If no, schedule callback. Do not proceed with intake.","origin":"spine","locked":true,"mandatoryGate":true},{"id":"script_reassure","scope":"lead","kind":"script","label":"Reassurance (read verbatim)","script":"My team focuses specifically on hotel trafficking cases. Anything you share stays confidential between you and the law firm. My role is not to judge or form opinions, only to gather the facts so the legal team can determine the best next steps. There''s no need to censor yourself. If you need to pause, take a break, or skip any question, just let me know. There are no right or wrong answers. If a question doesn''t apply, just tell me and we''ll keep moving.","origin":"script","locked":true},{"id":"s_threshold","scope":"lead","kind":"section","label":"Threshold","origin":"spine","locked":true},{"id":"g_victim","scope":"lead","kind":"bool","vital":true,"label":"Were you or a loved one a victim of sex trafficking or forced prostitution at any hotel or motel?","origin":"spine","locked":true},{"id":"poa_nok_confirmed","scope":"lead","kind":"bool","label":"POA / NOK authority confirmed","origin":"spine","locked":true},{"id":"g_at_hotel","scope":"lead","kind":"gate","gateType":"dq","vital":true,"label":"Did this occur at a hotel or motel?","agentNote":"If NO,