,"Parking lot","None"],"origin":"spine","locked":true},{"id":"housekeeping_entered","scope":"property","kind":"bool","label":"Did housekeeping enter the room while you were there?","origin":"spine","locked":true},{"id":"towel_change_freq","scope":"property","kind":"text","label":"How often were towels changed?","origin":"spine","locked":true},{"id":"sheet_change_freq","scope":"property","kind":"text","label":"How often were sheets changed?","origin":"spine","locked":true},{"id":"dnd_long_periods","scope":"property","kind":"bool","label":"Was a Do Not Disturb sign used for long periods?","origin":"spine","locked":true},{"id":"condoms_visible","scope":"property","kind":"bool","label":"Were condoms frequently visible in the room or trash?","origin":"spine","locked":true},{"id":"hk_staff","scope":"lead","kind":"section","label":"Staff Awareness","origin":"spine","locked":true},{"id":"staff_interact_traffk","scope":"property","kind":"bool","label":"Did hotel staff ever interact with the trafficker?","origin":"spine","locked":true},{"id":"staff_interact_victim","scope":"property","kind":"bool","label":"Did hotel staff ever interact with you directly?","origin":"spine","locked":true},{"id":"mgmt_intervened","scope":"property","kind":"bool","label":"Did management/staff ever attempt to intervene or confront anyone?","origin":"spine","locked":true},{"id":"violence_public_areas","scope":"property","kind":"bool","label":"Was there violence or confrontation in the lobby, hallways, or parking lot?","origin":"spine","locked":true},{"id":"drug_paraphernalia","scope":"property","kind":"bool","label":"Was there drug paraphernalia visible in the room?","origin":"spine","locked":true},{"id":"staff_witnessed_drugs","scope":"property","kind":"bool","label":"Did any staff witness intoxication or drug use?","origin":"spine","locked":true},{"id":"staff_knowledge_other","scope":"property","kind":"longtext","label":"Anything else that made it obvious the motel knew what was happening?","origin":"spine","locked":true},{"id":"landmarks","scope":"property","kind":"longtext","label":"Landmarks the claimant recognized nearby (corroborating detail)","origin":"spine","locked":true},{"id":"hk_variance","scope":"lead","kind":"section","label":"Variance (only if different at this property)","origin":"spine","locked":true},{"id":"has_variance","scope":"property","kind":"bool","label":"Was the trafficker or control method DIFFERENT at this property?","origin":"spine","locked":true},{"id":"variance_trafficker","scope":"property","kind":"text","label":"Different trafficker (name/alias)","origin":"spine","locked":true},{"id":"variance_control","scope":"property","kind":"multiselect","label":"Different control methods (select all)","options":["Physical force","Threats","Drugs","Debt bondage","Isolation","Other"],"origin":"spine","locked":true},{"id":"variance_notes","scope":"property","kind":"longtext","label":"Variance notes","origin":"spine","locked":true},{"id":"s_control","scope":"lead","kind":"section","label":"Control / Coercion","agentNote":"DO NOT LET THEM RAMBLE. Keep to the questions.","origin":"spine","locked":true},{"id":"was_controlled","scope":"lead","kind":"bool","label":"Was someone else controlling or forcing you to engage in sex acts?","origin":"spine","locked":true},{"id":"control_methods","scope":"lead","kind":"multiselect","label":"How were you controlled? (select all)","agentNote":"DO NOT READ THE LIST. Mark what they describe.","options":["Physical force","Threats","Drugs","Debt bondage","Isolation","Controlled money","Controlled ID/documents","Controlled phone","Emotional/psychological","Other"],"origin":"spine","locked":true},{"id":"could_refuse","scope":"lead","kind":"bool","label":"Were you able to refuse without consequences?","origin":"spine","locked":true},{"id":"had_phone_money_id","scope":"lead","kind":"bool","label":"Did you have access to your own phone, money, and ID during this time?","origin":"spine","locked":true},{"id":"s_recruit","scope":"lead","kind":"section","label":"How You Met","origin":"spine","locked":true},{"id":"met_how","scope":"lead","kind":"longtext","label":"How did you first meet the trafficker?","origin":"spine","locked":true},{"id":"met_where","scope":"lead","kind":"text","label":"Where did you first meet them? (City/State)","origin":"spine","locked":true},{"id":"met_age","scope":"lead","kind":"int","label":"How old were you when you first met them?","origin":"spine","locked":true},{"id":"initial_relationship","scope":"lead","kind":"text","label":"What was your relationship to them at first?","origin":"spine","locked":true},{"id":"promises_made","scope":"lead","kind":"multiselect","label":"Did they promise you anything? (select all)","options":["Love/relationship","Money","Job","Housing","Modeling/career","Travel","Drugs","Protection","Other"],"origin":"spine","locked":true},{"id":"provided_early","scope":"lead","kind":"multiselect","label":"Did they provide anything early on? (select all)","options":["Money","Gifts","Housing","Drugs","Clothing","Phone","Other"],"origin":"spine","locked":true},{"id":"topic_first_arose","scope":"lead","kind":"longtext","label":"How did the topic of sex work first come up?","origin":"spine","locked":true},{"id":"used_deception","scope":"lead","kind":"bool","label":"Did they use deception or false promises to get you involved?","origin":"spine","locked":true},{"id":"deception_detail","scope":"lead","kind":"text","label":"What were you told?","origin":"spine","locked":true},{"id":"s_recruit2","scope":"lead","kind":"section","label":"Early Control & Movement","origin":"spine","locked":true},{"id":"isolated_early","scope":"lead","kind":"bool","label":"Did they isolate you from friends or family early on?","origin":"spine","locked":true},{"id":"asked_to_travel","scope":"lead","kind":"bool","label":"Did they ask you to travel or relocate?","origin":"spine","locked":true},{"id":"taken_where","scope":"lead","kind":"text","label":"Where did they take you? (City/State or N/A)","origin":"spine","locked":true},{"id":"time_to_commercial","scope":"lead","kind":"text","label":"How soon after meeting did commercial sex begin?","origin":"spine","locked":true},{"id":"took_kept_items","scope":"lead","kind":"multiselect","label":"Did they take or keep any of the following? (select all)","options":["ID/documents","Money","Phone","Bank cards","Personal belongings","None"],"origin":"spine","locked":true},{"id":"intro_other_victims","scope":"lead","kind":"bool","label":"Were you introduced to other victims or girls working for the trafficker?","origin":"spine","locked":true},{"id":"s_money","scope":"lead","kind":"section","label":"Acts & Money","origin":"spine","locked":true},{"id":"acts_types","scope":"lead","kind":"multiselect","label":"To the extent you''re comfortable: did the acts involve vaginal, anal, or oral sex?","options":["Vaginal","Anal","Oral"],"origin":"spine","locked":true},{"id":"money_exchanged","scope":"lead","kind":"bool","label":"Was money exchanged for the sex acts?","origin":"spine","locked":true},{"id":"money_recipients","scope":"lead","kind":"multiselect","label":"Who received the money? (select all)","options":["Trafficker","You","Both","Other"],"origin":"spine","locked":true},{"id":"kept_any_money","scope":"lead","kind":"bool","label":"Did you personally keep any of the money?","origin":"spine","locked":true},{"id":"harmed_if_short","scope":"lead","kind":"bool","label":"Were you threatened or harmed if you didn''t make enough money?","origin":"spine","locked":true},{"id":"s_traffk","scope":"lead","kind":"section","label":"Trafficker Identification","origin":"spine","locked":true},{"id":"trafficker_known","scope":"lead","kind":"bool","label":"Do you know the trafficker''s name or aliases?","origin":"spine","locked":true},{"id":"trafficker_names","scope":"lead","kind":"text","label":"What name or aliases did they use?","origin":"spine","locked":true},{"id":"trafficker_desc","scope":"lead","kind":"multiselect","label":"Can you describe the trafficker? (select all)","options":["Male","Female","Tattoos","Distinctive features","Race/ethnicity noted","Approx age","Other"],"origin":"spine","locked":true},{"id":"other_solicit_locations","scope":"lead","kind":"text","label":"Other businesses/locations where the trafficker solicited or abducted girls?","origin":"spine","locked":true},{"id":"s_evidence","scope":"lead","kind":"section","label":"Evidence & Red Flags","origin":"spine","locked":true},{"id":"clothing_types","scope":"lead","kind":"multiselect","label":"What clothing were you typically wearing? (select all)","options":["Lingerie","Revealing","Street clothes","Provided by trafficker","Other"],"origin":"spine","locked":true},{"id":"underdressed_public","scope":"lead","kind":"bool","label":"Ever outside underdressed during cold or rainy weather?","origin":"spine","locked":true},{"id":"visibly_distressed_public","scope":"lead","kind":"bool","label":"Ever visibly injured, bruised, distressed, intoxicated, or disoriented in public hotel areas?","origin":"spine","locked":true},{"id":"has_social_media","scope":"lead","kind":"bool","label":"Any social media posts, stories, or archived posts from this time?","origin":"spine","locked":true},{"id":"evidence_items","scope":"lead","kind":"multiselect","label":"Any evidence related to the hotel or trafficker? (select all)","options":["Photos","Texts/messages","Receipts","Witnesses","Police report","Medical records","Other"],"origin":"spine","locked":true},{"id":"s_legal","scope":"lead","kind":"section","label":"Legal / Record History","origin":"spine","locked":true},{"id":"felony_convicted","scope":"lead","kind":"bool","label":"Have you ever been convicted of a felony?","origin":"spine","locked":true},{"id":"felony_count","scope":"lead","kind":"select","label":"How many felony convictions?","options":["1","2-3","4+","Not sure"],"origin":"spine","locked":true},{"id":"felony_types","scope":"lead","kind":"multiselect","label":"What type of felony convictions? (select all)","options":["Drug","Theft/property","Violent","Solicitation/prostitution","Fraud","Other"],"origin":"spine","locked":true},{"id":"felony_years","scope":"lead","kind":"text","label":"Approximately what years? (exact or range)","origin":"spine","locked":true},{"id":"felony_during_traffic","scope":"lead","kind":"bool","label":"Were any convictions during the same period as the trafficking?","origin":"spine","locked":true},{"id":"open_cases","scope":"lead","kind":"longtext","label":"Any open felony cases, warrants, probation, or parole?","origin":"spine","locked":true},{"id":"open_case_status","scope":"lead","kind":"text","label":"Current status?","origin":"spine","locked":true},{"id":"bankruptcy","scope":"lead","kind":"text","label":"Ever filed for bankruptcy? If yes, what type and when?","origin":"spine","locked":true},{"id":"aliases","scope":"lead","kind":"text","label":"Ever used another name or alias that may appear on records?","origin":"spine","locked":true},{"id":"s_narrative","scope":"lead","kind":"section","label":"Narrative & Safety","origin":"spine","locked":true},{"id":"narrative","scope":"lead","kind":"longtext","label":"In your own words, keep it general and factual: how did the trafficking occur at that hotel?","origin":"spine","locked":true},{"id":"visible_to_staff","scope":"lead","kind":"longtext","label":"What details do you remember that would have been visible to hotel staff?","origin":"spine","locked":true},{"id":"anything_missed","scope":"lead","kind":"longtext","label":"Anything we didn''t cover that you want the legal team to know?","origin":"spine","locked":true},{"id":"ongoing_safety","scope":"lead","kind":"bool","label":"Do you have ongoing safety concerns today?","origin":"spine","locked":true},{"id":"current_treatment","scope":"lead","kind":"bool","label":"Are you currently receiving medical or mental health treatment related to this?","origin":"spine","locked":true},{"id":"s_comms","scope":"lead","kind":"section","label":"Safe Contact","origin":"spine","locked":true},{"id":"comms_monitored","scope":"lead","kind":"bool","label":"Are the claimant''s communications monitored by anyone?","origin":"spine","locked":true},{"id":"comms_safe_channels","scope":"lead","kind":"multiselect","label":"Safe contact channels (select all)","options":["Text","Call","Voicemail","Email"],"origin":"spine","locked":true},{"id":"comms_safe_window","scope":"lead","kind":"text","label":"Safest time and method for follow-up contact","origin":"spine","locked":true},{"id":"s_closing","scope":"lead","kind":"section","label":"Closing","origin":"spine","locked":true},{"id":"script_closing","scope":"lead","kind":"script","label":"Closing script (read verbatim)","script":"Thank you. That completes the verification questions. The next step is internal review. If additional details are needed, someone may follow up. Please do not delete any messages, photos, location history, or records related to this matter. Because of the complexity of this claim, there can be delays while we wait for the courts or defending parties to respond. This is normal and no indication of an outcome. We''d like to check in every 30 to 45 days with updates or just to let you know we''re still working toward resolution.","origin":"script","locked":true}]'::jsonb,
  '["s_warm_welcome","s_open","script_intro","safe_to_speak","script_reassure","s_threshold","g_victim","poa_nok_confirmed","g_at_hotel","g_can_identify","s_ip","ip_first","ip_last","ip_dob","ip_ssn","ip_phone","ip_email","ip_deceased","ip_dod","s_caller","caller_type","caller_first","caller_last","caller_phone","caller_email","caller_dob","caller_ssn","is_legal_rep","caller_relation_ip","best_time","s_mail","mail_addr1","mail_addr2","mail_city","mail_state","mail_zip","s_ec","script_ec","ec_first","ec_last","ec_phone","ec_address","ec_relationship","ec_permission","ec_email","ec_may_leave_msg","ec_message_script","s_properties","property_lookup","name_as_recalled","remembered_brand","stay_month","stay_duration","room_floor","age_at_time","under_18","acts_count_here","hk_core","who_booked_paid","payment_method","men_per_day","asked_staff_for_help","asked_whom","police_emt_called","hk_ops","repeatedly_same_motel","specific_rooms_req","room_change_freq","visitors_check_desk","men_waiting_areas","housekeeping_entered","towel_change_freq","sheet_change_freq","dnd_long_periods","condoms_visible","hk_staff","staff_interact_traffk","staff_interact_victim","mgmt_intervened","violence_public_areas","drug_paraphernalia","staff_witnessed_drugs","staff_knowledge_other","landmarks","hk_variance","has_variance","variance_trafficker","variance_control","variance_notes","s_control","was_controlled","control_methods","could_refuse","had_phone_money_id","s_recruit","met_how","met_where","met_age","initial_relationship","promises_made","provided_early","topic_first_arose","used_deception","deception_detail","s_recruit2","isolated_early","asked_to_travel","taken_where","time_to_commercial","took_kept_items","intro_other_victims","s_money","acts_types","money_exchanged","money_recipients","kept_any_money","harmed_if_short","s_traffk","trafficker_known","trafficker_names","trafficker_desc","other_solicit_locations","s_evidence","clothing_types","underdressed_public","visibly_distressed_public","has_social_media","evidence_items","s_legal","felony_convicted","felony_count","felony_types","felony_years","felony_during_traffic","open_cases","open_case_status","bankruptcy","aliases","s_narrative","narrative","visible_to_staff","anything_missed","ongoing_safety","current_treatment","s_comms","comms_monitored","comms_safe_channels","comms_safe_window","s_closing","script_closing"]'::jsonb);

